import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"效果评估入门","description":"解释怎样评估 AI 输出效果：建立固定测试集与基线、选择人工评审、规则指标与 LLM-as-judge，并读懂公开基准测试分数。","frontmatter":{"description":"解释怎样评估 AI 输出效果：建立固定测试集与基线、选择人工评审、规则指标与 LLM-as-judge，并读懂公开基准测试分数。"},"headers":[],"relativePath":"prompting/evaluation.md","filePath":"prompting/evaluation.md","lastUpdated":null}'),i={name:"prompting/evaluation.md"};function d(o,t,n,s,h,g){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="效果评估入门" tabindex="-1">效果评估入门 <a class="header-anchor" href="#效果评估入门" aria-label="Permalink to &quot;效果评估入门&quot;">​</a></h1><blockquote><p><strong>一句话结论：</strong> 评估的核心是把“感觉变好了”变成“可比较的记录”：固定一组测试题，先测出基线，每次改 Prompt、换模型或调参数后重跑同一组测试，用分数而不是印象决定采纳还是回滚。</p></blockquote><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已阅读 <a href="/prompting/basics">Prompt 入门</a>，知道一个 Prompt 通常包含任务、上下文、格式与约束。</li><li>已阅读 <a href="/llm/inference-decoding">推理与解码</a>更好——采样随机性解释了为什么单次输出不足为凭；没读也不影响理解本页。</li><li>不要求编程；本页示例只用表格和手工推演。</li></ul><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>读完后，你应该能够：</p><ul><li>解释为什么“试了几个例子觉得不错”不能作为效果结论。</li><li>为自己的任务建立一个小的固定测试集和基线记录。</li><li>按任务特点选择评估方式：人工评审、规则指标或 LLM-as-judge。</li><li>说出公开基准测试（Benchmark）分数与自身任务评估的关系。</li><li>识别评估中的常见错误：测试题泄漏、只看总分、judge 偏差。</li></ul><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="为什么-看起来不错-不可靠" tabindex="-1">为什么“看起来不错”不可靠 <a class="header-anchor" href="#为什么-看起来不错-不可靠" aria-label="Permalink to &quot;为什么“看起来不错”不可靠&quot;">​</a></h3><p>三个原因叠加，让凭印象的判断系统性失真：</p><ul><li><strong>随机性</strong>：采样参数会让同一个 Prompt 每次输出不同（详见<a href="/llm/inference-decoding">推理与解码</a>）；一次成功可能只是抽中了好的那种。</li><li><strong>选择性记忆</strong>：改动之后，成功的例子印象深，失败的例子容易被忽略；没有固定记录，几次之后就不记得真实比例。</li><li><strong>不可比较</strong>：换模型、改 Prompt、调参数之后，如果输入和评判标准也跟着变，就没有公平的比较基准。</li></ul><p>评估要解决的正是这三件事：控制输入不变、控制标准不变、把结果记成可比较的数字。</p><h3 id="测试集-固定一份考卷" tabindex="-1">测试集：固定一份考卷 <a class="header-anchor" href="#测试集-固定一份考卷" aria-label="Permalink to &quot;测试集：固定一份考卷&quot;">​</a></h3><p>把真实任务里的代表性输入固定下来，形成一份小考卷：</p><ul><li>规模：认真做可以从 20-50 题起步；本页演示用 10 题是为了篇幅，真实场景太少看不出差异。</li><li>覆盖：既要有常见情形，也要有边界情形——超长输入、缺少必要信息、容易混淆的说法。</li><li>标注：每题记下“期望要点”，不一定是唯一标准答案，例如“必须包含退货期限”“必须拒绝报价请求”“输出必须是 JSON”。</li><li>防泄漏：不要把测试题直接贴进正在迭代的 Prompt 里当示例，也别在同一份考卷上反复“刷题”；用过一段时间的考卷要更换和补充，防止把测试集用成了训练集。</li></ul><h3 id="指标与基线" tabindex="-1">指标与基线 <a class="header-anchor" href="#指标与基线" aria-label="Permalink to &quot;指标与基线&quot;">​</a></h3><p>先回答“什么叫好”，再动手测：</p><ul><li><strong>正确性</strong>：答案是否与事实或给定资料一致。</li><li><strong>完整性</strong>：要求覆盖的要点是否都覆盖了。</li><li><strong>格式合规</strong>：是否按要求的结构、字段、语言输出。</li><li><strong>引用可溯源</strong>：声称的来源是否真实存在（RAG 场景的关键指标）。</li><li><strong>延迟与成本</strong>：Token 消耗、响应时间——它们也是效果的一部分。</li></ul><p>能量化才能比较。格式、字段、引用编号这类可以用规则自动检查；语义质量需要人工或模型评判。<strong>基线</strong>是改动前的第一次完整记录：没有基线，任何“变好了”都缺少参照物。</p><h3 id="三种评估方式" tabindex="-1">三种评估方式 <a class="header-anchor" href="#三种评估方式" aria-label="Permalink to &quot;三种评估方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>适合判断什么</th><th>优点</th><th>主要局限</th></tr></thead><tbody><tr><td>人工评审</td><td>少量高质量判断、最终验收</td><td>最可信</td><td>慢、成本高、多人标准会漂移</td></tr><tr><td>规则指标</td><td>格式、字段、引用、可验证结果</td><td>快、客观、可自动化</td><td>覆盖不了语义质量</td></tr><tr><td>LLM-as-judge</td><td>语义质量的批量初筛与对比</td><td>快、可扩展、能给出理由</td><td>有系统偏差，需人工抽查校准</td></tr></tbody></table><p>三者通常组合使用：规则指标打底，LLM-as-judge 跑批量，人工评审做抽查和终审。</p><h3 id="llm-as-judge-让模型当阅卷人" tabindex="-1">LLM-as-judge：让模型当阅卷人 <a class="header-anchor" href="#llm-as-judge-让模型当阅卷人" aria-label="Permalink to &quot;LLM-as-judge：让模型当阅卷人&quot;">​</a></h3><p>做法：把“待评输出 + 评分标准（量规）”交给一个模型，让它按标准逐项打分并给出理由。量规越具体，judge 越稳定：“按 0-2 分评价回答是否解决了用户的问题，0 = 未解决……”远好于“这个回答好不好”。</p><p>judge 也是语言模型，会犯系统性的错，已知偏差包括：</p><ul><li><strong>位置偏差</strong>：A/B 对比时，评判结果受两个答案的摆放顺序影响。</li><li><strong>长度偏好</strong>：更长的答案常被打更高分，哪怕信息量相同。</li><li><strong>自我偏好</strong>：judge 倾向于偏好与自己风格相似的输出。</li></ul><p>缓解办法：对比评测时交换顺序各评一次；量规写具体、给例子；定期抽取一部分让人工复核，确认 judge 与人工的口径一致。</p><h3 id="基准测试分数怎么读" tabindex="-1">基准测试分数怎么读 <a class="header-anchor" href="#基准测试分数怎么读" aria-label="Permalink to &quot;基准测试分数怎么读&quot;">​</a></h3><p>基准测试（Benchmark）是公开的标准考试，例如 MMLU（多领域知识问答）、HumanEval 与 SWE-bench（代码）、GPQA（高难度科学问答）。模型卡上的分数多半来自这类榜单。</p><p>公开分数的用途与边界：</p><ul><li>能用来估计一个模型的大致能力段位，做粗粒度选型。</li><li>不能直接预测它在你的任务上的表现：考题可能混进了训练数据（数据污染），任务分布也和你的场景不同，何况你的 Prompt 写法与考法并不一样。</li><li>正确用法：把公开分数当地图，把自己的测试集当考卷——选型时先看地图缩小范围，再用考卷做最终决定。</li></ul><h3 id="评测驱动的迭代循环" tabindex="-1">评测驱动的迭代循环 <a class="header-anchor" href="#评测驱动的迭代循环" aria-label="Permalink to &quot;评测驱动的迭代循环&quot;">​</a></h3><p>把以上内容连成工作方式：</p><ol><li>固定测试集与指标。</li><li>跑出基线并记录。</li><li>一次只改一处（Prompt、模型或参数）。</li><li>重跑整份考卷。</li><li>对比分数，决定采纳或回滚。</li><li>定期更换、扩充考卷，重新校准 judge。</li></ol><p>“一次只改一处”与实验里控制变量是同一件事——同时改 Prompt 又换模型，分数变了也不知道该归功谁。</p><h2 id="最小推演-10-题考卷对比" tabindex="-1">最小推演：10 题考卷对比 <a class="header-anchor" href="#最小推演-10-题考卷对比" aria-label="Permalink to &quot;最小推演：10 题考卷对比&quot;">​</a></h2><p>虚构任务：客服助手根据产品文档回答售后问题，要求每条答案注明来源文档编号。</p><table tabindex="0"><thead><tr><th>指标</th><th style="text-align:right;">原 Prompt（基线）</th><th style="text-align:right;">新 Prompt</th></tr></thead><tbody><tr><td>要点覆盖（10 题中）</td><td style="text-align:right;">7</td><td style="text-align:right;">9</td></tr><tr><td>格式合规（10 题中）</td><td style="text-align:right;">8</td><td style="text-align:right;">10</td></tr><tr><td>引用真实可溯源（10 题中）</td><td style="text-align:right;">6</td><td style="text-align:right;">9</td></tr><tr><td>平均响应时间</td><td style="text-align:right;">3 秒</td><td style="text-align:right;">4 秒</td></tr></tbody></table><p>读表方式比数字本身重要：</p><ul><li>新 Prompt 在三个质量指标上全面更好，但响应时间变慢——质量提升是用成本换的，要不要采纳取决于业务更在意哪个。</li><li>引用真实从 6 到 9 的提升幅度最大，说明这次改动主要修正了“编造来源”的问题；这也提示下一轮迭代值得在引用核对上继续投入。</li><li>10 题只是演示：这么小的样本里，一两题的波动就可能只是随机性。真实测试集要更大，并且要看每题的变化明细，而不是只看总分。</li></ul><h2 id="对比表" tabindex="-1">对比表 <a class="header-anchor" href="#对比表" aria-label="Permalink to &quot;对比表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>做法与概念</th><th>回答的问题</th><th>优点</th><th>主要局限</th></tr></thead><tbody><tr><td>随手试几个例子</td><td>“这个输出好不好”</td><td>快、零成本</td><td>有偏、不可比、易被随机性欺骗</td></tr><tr><td>固定测试集 + 基线</td><td>“这次改动有没有变好”</td><td>可比较、可回归</td><td>需要前期建设与维护</td></tr><tr><td>公开 Benchmark</td><td>“模型大致能力段位”</td><td>可横向比较</td><td>与具体任务有差距、可能数据污染</td></tr><tr><td>LLM-as-judge</td><td>“大量输出的语义质量”</td><td>快、可扩展</td><td>有系统偏差，需人工校准</td></tr></tbody></table><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“改了 Prompt 看两个例子变好就是变好”</strong>：单次输出受采样随机性影响，少量例子没有统计意义；固定测试集重跑才有可比性。</li><li><strong>“测试集建好就一劳永逸”</strong>：考卷会泄漏——题目混进示例或被反复“刷题”后，高分不再反映真实能力；要定期更换与扩充。</li><li><strong>“公开 Benchmark 分数高就一定适合我的任务”</strong>：分数来自别人的考题，存在数据污染与任务分布差异；最终要用自己的考卷验证。</li><li><strong>“LLM-as-judge 是客观的”</strong>：judge 有位置偏差、长度偏好和自我偏好，只能做初筛，重要决策要人工抽查校准。</li><li><strong>“只看一个总分”</strong>：总分上升可能掩盖某项退步，比如要点覆盖变好但引用真实性下降；要分指标看。</li><li><strong>“评估只管质量不管成本”</strong>：延迟、Token 消耗也是效果的一部分；质量提升若以数倍成本为代价，未必值得。</li></ul><h2 id="自测问题" tabindex="-1">自测问题 <a class="header-anchor" href="#自测问题" aria-label="Permalink to &quot;自测问题&quot;">​</a></h2><h3 id="_1-为什么改了-prompt-之后要重跑整份测试集-而不是只拿新的输出看看" tabindex="-1">1. 为什么改了 Prompt 之后要重跑整份测试集，而不是只拿新的输出看看？ <a class="header-anchor" href="#_1-为什么改了-prompt-之后要重跑整份测试集-而不是只拿新的输出看看" aria-label="Permalink to &quot;1. 为什么改了 Prompt 之后要重跑整份测试集，而不是只拿新的输出看看？&quot;">​</a></h3><details><summary>查看答案</summary><p>单次输出受采样随机性影响，凭印象无法区分“真的变好”和“这次恰好抽到了好结果”。整份测试集在相同输入、相同标准下重跑，才能和基线公平对比，也才能发现改动在某些题型上造成的退步。</p></details><h3 id="_2-llm-as-judge-有哪些已知偏差-怎样缓解" tabindex="-1">2. LLM-as-judge 有哪些已知偏差？怎样缓解？ <a class="header-anchor" href="#_2-llm-as-judge-有哪些已知偏差-怎样缓解" aria-label="Permalink to &quot;2. LLM-as-judge 有哪些已知偏差？怎样缓解？&quot;">​</a></h3><details><summary>查看答案</summary><p>主要有位置偏差（对比结果受 A/B 顺序影响）、长度偏好（偏长的答案得分偏高）和自我偏好（偏爱自己风格的输出）。缓解：交换顺序各评一次、把评分量规写具体并给例子、定期抽取一部分由人工复核，确认 judge 与人工口径一致。</p></details><h3 id="_3-公开-benchmark-分数和你自己任务的评估是什么关系" tabindex="-1">3. 公开 Benchmark 分数和你自己任务的评估是什么关系？ <a class="header-anchor" href="#_3-公开-benchmark-分数和你自己任务的评估是什么关系" aria-label="Permalink to &quot;3. 公开 Benchmark 分数和你自己任务的评估是什么关系？&quot;">​</a></h3><details><summary>查看答案</summary><p>公开分数用于粗粒度选型，估计模型的大致能力段位；它不能预测你的任务表现，因为可能有数据污染、任务分布差异和 Prompt 写法差异。正确做法是先用公开分数缩小候选范围，再用自己任务的固定测试集做最终决定。</p></details><h3 id="_4-哪些指标适合用规则自动检查-哪些必须靠人工或-judge" tabindex="-1">4. 哪些指标适合用规则自动检查，哪些必须靠人工或 judge？ <a class="header-anchor" href="#_4-哪些指标适合用规则自动检查-哪些必须靠人工或-judge" aria-label="Permalink to &quot;4. 哪些指标适合用规则自动检查，哪些必须靠人工或 judge？&quot;">​</a></h3><details><summary>查看答案</summary><p>规则可查的是结构化、可判定的内容：输出格式、必含字段、长度范围、引用编号是否真实存在于资料中。语义质量——回答是否切题、要点是否覆盖、推理是否合理——规则写不出来，需要人工评审，或 LLM-as-judge 初筛加人工抽查。</p></details><h2 id="关联阅读" tabindex="-1">关联阅读 <a class="header-anchor" href="#关联阅读" aria-label="Permalink to &quot;关联阅读&quot;">​</a></h2><ul><li><strong>迭代对象：</strong> <a href="/prompting/basics">Prompt 入门</a>讲解 Prompt 的组成部分——评估就是验证这些改动是否有效的手段。</li><li><strong>评估对象：</strong> <a href="/llm/rag-agent">RAG 与 Agent</a>的检索质量、引用真实性与工具调用安全，都需要本页的方法来检验。</li><li><strong>理解随机性：</strong> <a href="/llm/inference-decoding">推理与解码</a>解释为什么单次输出不足为凭。</li><li><strong>随时查词：</strong> <a href="/glossary">术语表</a>汇总 Benchmark、LLM-as-judge 等术语。</li></ul><h2 id="官方或原始资料来源" tabindex="-1">官方或原始资料来源 <a class="header-anchor" href="#官方或原始资料来源" aria-label="Permalink to &quot;官方或原始资料来源&quot;">​</a></h2><ul><li><a href="https://arxiv.org/abs/2306.05685" target="_blank" rel="noreferrer">Zheng 等：Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena</a>：提出并系统分析 LLM-as-judge 方法与偏差的论文。</li><li><a href="https://arxiv.org/abs/2009.03300" target="_blank" rel="noreferrer">Hendrycks 等：Measuring Massive Multitask Language Understanding（MMLU）</a>：MMLU 基准的原始论文。</li><li><a href="https://arxiv.org/abs/2107.03374" target="_blank" rel="noreferrer">Chen 等：Evaluating Large Language Models Trained on Code（HumanEval）</a>：HumanEval 代码基准的原始论文。</li><li><a href="https://arxiv.org/abs/2310.06770" target="_blank" rel="noreferrer">Jimenez 等：SWE-bench: Can Language Models Resolve Real-World GitHub Issues?</a>：SWE-bench 基准的原始论文。</li><li><a href="https://genai.owasp.org/llm-top-10/" target="_blank" rel="noreferrer">OWASP：Top 10 for LLM Applications</a>：LLM 应用风险清单，可用于设计安全类测试用例。</li></ul>',57)])])}const m=a(i,[["render",d]]);export{p as __pageData,m as default};
